// TP : alarme de température pour une salle de classe.
#include <OneWire.h>
#include <DallasTemperature.h>

const int SONDE = 4;       // DQ de la DS18B20
const int BUZZER = 8;      // buzzer actif
const float SEUIL = 30.0;  // en °C

OneWire bus(SONDE);
DallasTemperature capteur(&bus);

void setup() {
  Serial.begin(9600);
  capteur.begin();
  pinMode(BUZZER, OUTPUT);
}

void loop() {
  capteur.requestTemperatures();         // mesure (750 ms)
  float t = capteur.getTempCByIndex(0);  // première sonde du bus
  Serial.print("Temperature : ");
  Serial.print(t);
  Serial.println(" C");

  if (t > SEUIL) {
    digitalWrite(BUZZER, HIGH);  // trop chaud : alarme
  } else {
    digitalWrite(BUZZER, LOW);
  }
}

